        "kind": "module",
        "content": "\"use client\"\nimport React from 'react';\nimport { BeforeAfterSlider } from './layout/BeforeAfterSlider';\n\nexport const metadata = {\n  name: \"Basic\",\n  description: \"An image comparison slider: one frame split by a draggable divider that wipes between two states.\",\n};\n\nfunction DraftPanel() {\n  return (\n    <div className=\"flex h-full w-full flex-col justify-end gap-3 bg-background-800 p-6\">\n      <div className=\"h-3 w-1/2 rounded bg-background-700\" />\n      <div className=\"h-3 w-2/3 rounded bg-background-700\" />\n      <div className=\"h-3 w-1/3 rounded bg-background-700\" />\n    </div>\n  );\n}\n\nfunction FinishedPanel() {\n  return (\n    <div className=\"flex h-full w-full flex-col justify-end gap-3 bg-gradient-to-br from-accent-600/40 to-background-800 p-6\">\n      <div className=\"h-3 w-1/2 rounded bg-accent-500/60\" />\n      <div className=\"h-3 w-2/3 rounded bg-foreground-50/30\" />\n      <div className=\"h-3 w-1/3 rounded bg-foreground-50/20\" />\n    </div>\n  );\n}\n\nexport function BasicBeforeAfter() {\n  return (\n    <div className=\"min-h-screen bg-background-950 p-8\">\n      <div className=\"mx-auto max-w-2xl space-y-4\">\n        <div>\n          <h1 className=\"text-lg font-semibold text-foreground-50\">Redesign comparison</h1>\n          <p className=\"text-sm text-foreground-400\">\n            Drag the divider, or focus the frame and use the arrow keys.\n          </p>\n        </div>\n\n        <BeforeAfterSlider\n          before={<DraftPanel />}\n          after={<FinishedPanel />}\n          beforeLabel=\"Draft\"\n          afterLabel=\"Shipped\"\n        />\n      </div>\n    </div>\n  );\n}\n",
        "entrypoint": true
