        "content": "'use client';\n\nimport { Label } from 'ui-lab-components/label';\nimport { List } from 'ui-lab-components/list';\nimport { Select } from 'ui-lab-components/select';\n\nconst timezones = [\n  { id: 'utc', label: 'UTC' },\n  { id: 'et', label: 'Eastern Time' },\n  { id: 'pt', label: 'Pacific Time' },\n];\n\nfunction SelectRowInline({ id, label, defaultValue }: { id: string; label: string; defaultValue?: string }) {\n  return (\n    <List.Item focusable={false} className=\"py-2\">\n      <List.Title><Label htmlFor={id}>{label}</Label></List.Title>\n      <List.Select defaultSelectedKey={defaultValue}>\n        <Select.Trigger id={id}><Select.Value /></Select.Trigger>\n        <Select.Content>\n          {timezones.map((timezone) => <Select.Item key={timezone.id} value={timezone.id}>{timezone.label}</Select.Item>)}\n        </Select.Content>\n      </List.Select>\n    </List.Item>\n  );\n}\n\nexport function SelectRowInlineDemo() {\n  return (\n    <List aria-label=\"Timezone settings\" spacing=\"sm\">\n      <SelectRowInline id=\"tz\" label=\"Timezone\" defaultValue=\"et\" />\n      <SelectRowInline id=\"tz2\" label=\"Secondary timezone\" defaultValue=\"utc\" />\n    </List>\n  );\n}\n",
